/* DhakaFin Signature — entire offline HTML/CSS/JS system (no web fonts or CDN) */
:root{--v2-paper:#f8f8f2;--v2-cream:#eff4eb;--v2-deep:#032f26;--v2-ink:#092d23;--v2-sage:#b9edc5;--v2-green:#087c5e;--v2-border:#dce8db;--v2-serif:Georgia,'Times New Roman',serif}
html{scroll-padding-top:105px}body.v2-page{background:#f8f9f5;color:var(--v2-ink);font-family:Inter,'Segoe UI',Arial,sans-serif;letter-spacing:-.005em;overflow-x:hidden}body.v2-page *{box-sizing:border-box}body.v2-page .site-container{width:min(1350px,calc(100% - 90px));margin-inline:auto}body.v2-page .ico{vertical-align:middle;display:inline-block;flex-shrink:0}
