.v2-hero{position:relative;background:radial-gradient(ellipse at 85% 40%,#095a47 0%,transparent 41%),linear-gradient(122deg,#053b2f,#03281f 62%,#032d24);color:#fff;isolation:isolate;overflow:hidden}.v2-hero:before{content:"";position:absolute;inset:0;z-index:-1;background-image:linear-gradient(#ffffff06 1px,transparent 1px),linear-gradient(90deg,#ffffff06 1px,transparent 1px);background-size:47px 47px;mask-image:linear-gradient(to left,#000,transparent 85%)}.v2-hero-inner{min-height:620px;display:grid;grid-template-columns:1.02fr .98fr;align-items:center;gap:6%;padding:86px 0 75px}.v2-hero-copy{min-width:0}.v2-crumb{display:flex;align-items:center;gap:14px;margin-bottom:57px;font-size:9px;font-weight:800;letter-spacing:.19em;color:#a9cfb9}.v2-crumb a{color:#c6e2cd}.v2-crumb a:hover{color:#fff}.v2-overline{font-size:10px;font-weight:800;letter-spacing:.2em;color:#bceec6;display:flex;gap:12px;align-items:center;margin-bottom:21px}.v2-overline i{width:26px;height:1px;background:#bceec6}.v2-overline span{opacity:.5}.v2-hero h1{margin:0;max-width:790px;font-size:clamp(53px,5.3vw,86px);line-height:1.06;letter-spacing:-.087em;font-weight:780;color:#fff}.v2-hero h1 em{font-family:var(--v2-serif);font-weight:400;letter-spacing:-.077em;color:#c3efc8;display:inline-block}.v2-hero-copy>p{font-size:16px;line-height:1.85;color:#c0d6c7;max-width:530px;margin:29px 0 34px}.v2-hero-links{display:flex;flex-wrap:wrap;gap:9px}.v2-hero-links a{display:inline-flex;align-items:center;justify-content:space-between;gap:30px;padding:16px 17px;min-height:51px;border-radius:7px;border:1px solid #8db5a255;color:#f4fff7;font-size:12px;font-weight:800;transition:background .2s,transform .2s}.v2-hero-links a:first-child{background:#b8f0c3;color:#0a4535;border-color:transparent}.v2-hero-links a:hover{background:#1f7259;color:white;transform:translateY(-2px)}.v2-hero-foot{display:flex;justify-content:space-between;padding-bottom:25px;gap:15px;color:#a1c6b4;font-size:9px;font-weight:800;letter-spacing