.v2-visual{position:relative;min-width:0;min-height:470px;border:1px solid #ffffff29;border-radius:16px;padding:29px;display:flex;flex-direction:column;box-shadow:0 30px 80px #011f1c7d;background:linear-gradient(153deg,#1c584d70,#092f2c75 55%,#052620c9);overflow:hidden;isolation:isolate}.v2-visual:before{position:absolute;z-index:-1;content:"";width:360px;height:360px;background:#56d69b13;border-radius:50%;left:-160px;bottom:-180px;box-shadow:0 0 160px 100px #4fa87d17}.v2-vis-head{display:flex;align-items:center;gap:11px;border-bottom:1px solid #ffffff20;padding-bottom:21px;color:#e8faec}.v2-vis-head span{font-size:10px;font-weight:900;letter-spacing:.19em;flex:1}.v2-vis-head b{font-size:9px;letter-spacing:.11em;color:#b9edc5;border:1px solid #ffffff29;padding:6px 8px;border-radius:4px}.v2-vis-title{font-size:clamp(36px,4vw,55px);line-height:1.06;letter-spacing:-.065em;font-weight:770;margin:38px 0 auto}.v2-vis-title em{font-family:var(--v2-serif);font-weight:400;color:#bfecc7}.v2-vis-bottom{border-top:1px solid #ffffff1d;margin-top:29px;padding-top:20px;display:flex;justify-content:space-between;gap:10px;color:#a9cdba;font-size:9px;font-weight:800;letter-spacing:.12em}.v2-vis-form{display:grid;gap:10px;margin-top:28px}.v2-vis-form>div{background:#ffffff0b;border:1px solid #ffffff1c;border-radius:8px;padding:15px 17px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px}.v2-vis-form small{color:#b9dac2;font-size:9px;font-weight:800;letter-spacing:.11em;width:100%}.v2-vis-form strong{display:flex;align-items:center;justify-content:space-between;gap:10px;width:100%;font-size:14px;font-weight:700}.v2-vis-form svg{color:#a1f3ba}.v2-visual-tool{background:linear-gradient(148deg,#164a3f,#072b27 68%,#02271e)}.v2-visual-tool .v2-vis-title{margin-bottom:0}.v2-visual-research{background:linear-gradient(145deg,#163a32,#0b2d27 70%,#1c4c3d)}.v2-paper{background:#ecf5e9;color:#173a2d;margin:24px 20px 10px;padding:24px 25px;box-shadow:12px 11px 0 #9